import numpy as np
from scipy.optimize import differential_evolution, minimize

def solve(alpha,k=3,diag=None):
 if diag is None: diag=np.zeros(k)
 inds=[(i,j) for i in range(k) for j in range(i+1,k)]
 def unpack(x):
  w=np.r_[x[:k-1],1-sum(x[:k-1])]; W=np.diag(diag).astype(float)
  for (i,j),v in zip(inds,x[k-1:]):W[i,j]=W[j,i]=v
  return w,W
 def calc(x):
  w,W=unpack(x); R=(W*w)@W; B=((1-W)*w)@(1-W)
  ar=R[W>1e-6].max(initial=0);br=B[W<1-1e-6].max(initial=0)
  return max(ar/alpha,br)+100*max(0,-min(w))
 res=differential_evolution(calc,[(0,1)]*(k-1+len(inds)),tol=1e-8,popsize=20,maxiter=2000)
 return 1/res.fun,unpack(res.x)
for a in [.1667,.17,.18,.19,.2,.201,.21]:
 v,par=solve(a)
 print(a,v,par)

